insert into public.flashcard_catalogue_material (version_id,catalogue_id,catalogue_card_id,front,back,note_type,variant,tags,suspended,subdeck_path) select '5d1a7759-32e0-42d8-a4d9-23206cddf8a3'::uuid,'EDX_ALEVEL_ENGLIT_9ET0_MARK',i.id,x.f,x.b,'basic','forward',x.t,true,x.p from jsonb_to_recordset($j$[{"k":"ppp-englit-9ET0-mark:243145cbecfb9851eb41","f":"How does Williams use lighting to present illusion in A Streetcar Named Desire?","b":"Model answer: Blanche avoids bright light, suggesting her fear of exposure. Marking points: Analyse a stage technique and link it to illusion and context. Common trap: Retelling Blanche's past without analysing the lighting.","t":["PPP::Edexcel::9ET0","PPP::Deck::mark_scheme","PPP::Paper::assessment-skills","PPP::Topic::assessment-skills","PPP::Class::mark_scheme"],"p":"Edexcel A-level English Literature 9ET0 – Exam technique::Assessment skills::Assessment skills:: Assessment skills"},{"k":"ppp-englit-9ET0-mark:4e1fc699abf7747a4ef6","f":"Compare how Frankenstein and The Handmaid's Tale use narrative structure to shape knowledge.","b":"Model answer: Shelley's embedded narratives offer competing perspectives, while Atwood's night sections interrupt Gilead's daily routine. Marking points: Compare narrative methods, support the argument with both texts, and relate relevant context. Common trap: Discussing each novel separately with no connection.","t":["PPP::Edexcel::9ET0","PPP::Deck::mark_scheme","PPP::Paper::assessment-skills","PPP::Topic::assessment-skills","PPP::Class::mark_scheme"],"p":"Edexcel A-level English Literature 9ET0 – Exam technique::Assessment skills::Assessment skills:: Assessment skills"},{"k":"ppp-englit-9ET0-mark:e7cff2a62fd4fcdf9261","f":"How does Iago create suspicion in Othello?","b":"Model answer: Iago echoes Othello's words and withholds apparent knowledge, making Othello supply the fear. Marking points: Analyse dramatic language, develop an argument and engage with relevant context and critical interpretations. Common trap: Retelling the plot without examining dramatic method.","t":["PPP::Edexcel::9ET0","PPP::Deck::mark_scheme","PPP::Paper::assessment-skills","PPP::Topic::assessment-skills","PPP::Class::mark_scheme"],"p":"Edexcel A-level English Literature 9ET0 – Exam technique::Assessment skills::Assessment skills:: Assessment skills"},{"k":"ppp-englit-9ET0-mark:78eba1220e9d11c63557","f":"Compare how two poems present place, using Blake's London and another Romantic poem.","b":"Model answer: Blake's moving speaker presents an oppressive city, while Wordsworth surveys the landscape in Tintern Abbey. Marking points: Analyse both poets' methods, connect the poems and integrate relevant context. Common trap: Writing a historical context paragraph without linking it to the poems.","t":["PPP::Edexcel::9ET0","PPP::Deck::mark_scheme","PPP::Paper::assessment-skills","PPP::Topic::assessment-skills","PPP::Class::mark_scheme"],"p":"Edexcel A-level English Literature 9ET0 – Exam technique::Assessment skills::Assessment skills:: Assessment skills"},{"k":"ppp-englit-9ET0-mark:c394f7ed7c7cff8f6a6c","f":"What is the time allowed for A-level English Literature Paper 1, Drama?","b":"2 hours 15 minutes","t":["PPP::Edexcel::9ET0","PPP::Deck::mark_scheme","PPP::Paper::assessment-skills","PPP::Topic::assessment-skills","PPP::Class::mark_scheme"],"p":"Edexcel A-level English Literature 9ET0 – Exam technique::Assessment skills::Assessment skills:: Assessment skills"},{"k":"ppp-englit-9ET0-mark:2b5b226073d83c4fbbd9","f":"How many marks are available for the Shakespeare essay in A-level Drama?","b":"35","t":["PPP::Edexcel::9ET0","PPP::Deck::mark_scheme","PPP::Paper::assessment-skills","PPP::Topic::assessment-skills","PPP::Class::mark_scheme"],"p":"Edexcel A-level English Literature 9ET0 – Exam technique::Assessment skills::Assessment skills:: Assessment skills"},{"k":"ppp-englit-9ET0-mark:2016a8a34c6f7fb4ae45","f":"How many marks are available for the other drama essay in A-level Drama?","b":"25","t":["PPP::Edexcel::9ET0","PPP::Deck::mark_scheme","PPP::Paper::assessment-skills","PPP::Topic::assessment-skills","PPP::Class::mark_scheme"],"p":"Edexcel A-level English Literature 9ET0 – Exam technique::Assessment skills::Assessment skills:: Assessment skills"},{"k":"ppp-englit-9ET0-mark:9fc604735c50151b5dcc","f":"What is the time allowed for A-level English Literature Paper 2, Prose?","b":"1 hour 15 minutes","t":["PPP::Edexcel::9ET0","PPP::Deck::mark_scheme","PPP::Paper::assessment-skills","PPP::Topic::assessment-skills","PPP::Class::mark_scheme"],"p":"Edexcel A-level English Literature 9ET0 – Exam technique::Assessment skills::Assessment skills:: Assessment skills"},{"k":"ppp-englit-9ET0-mark:bc0a89e62931449c5144","f":"How many marks are available for the A-level comparative prose essay?","b":"40","t":["PPP::Edexcel::9ET0","PPP::Deck::mark_scheme","PPP::Paper::assessment-skills","PPP::Topic::assessment-skills","PPP::Class::mark_scheme"],"p":"Edexcel A-level English Literature 9ET0 – Exam technique::Assessment skills::Assessment skills:: Assessment skills"},{"k":"ppp-englit-9ET0-mark:c6aad16bedd9d4bca9c1","f":"What is the time allowed for A-level English Literature Paper 3, Poetry?","b":"2 hours 15 minutes","t":["PPP::Edexcel::9ET0","PPP::Deck::mark_scheme","PPP::Paper::assessment-skills","PPP::Topic::assessment-skills","PPP::Class::mark_scheme"],"p":"Edexcel A-level English Literature 9ET0 – Exam technique::Assessment skills::Assessment skills:: Assessment skills"},{"k":"ppp-englit-9ET0-mark:890ce6721835f454e2d0","f":"How many marks are available for each A-level Poetry section?","b":"30","t":["PPP::Edexcel::9ET0","PPP::Deck::mark_scheme","PPP::Paper::assessment-skills","PPP::Topic::assessment-skills","PPP::Class::mark_scheme"],"p":"Edexcel A-level English Literature 9ET0 – Exam technique::Assessment skills::Assessment skills:: Assessment skills"},{"k":"ppp-englit-9ET0-mark:1c2b92451a49e6d1b72b","f":"Which assessment objective assesses connections across litera